    var options=['リセット','HA','HB','HC','HD','HS','AB','AC','AD','AS','BC','BD','BS','CD','CS','DS'];
    options.forEach(function(x){ var op=document.createElement('option'); op.value=x; op.textContent=x; select.appendChild(op); });
    var btn=make('button','v082h-mini','入力'); btn.type='button';
    btn.addEventListener('click',function(){ applyEvPreset(side, select.value); });
