    var abilityA=q('v082hAttackerAbilityZone'), abilityD=q('v082hDefenderAbilityZone'), item=q('v082hAttackerItemZone'), tera=q('v082hAttackerTeraZone'), move=q('v082hMoveZone');
    if(abilityA) abilityA.appendChild(zone('v082hAbilityDetails','特性固有条件'));
    if(abilityD) abilityD.appendChild(zone('v082hDefenderAbilityDetails','防御側特性固有条件'));
