    ['flashFireActivated','stakeoutSwitchIn','supremeOverlordFaintedAllies','attackerSlowStart','attackerUnburden','attackerParadoxBoostStat','analyzeMovedLast','flowerGiftSupport','plusMinusSupport','batterySupport','powerSpotSupport'].forEach(function(id){ moveLabel(id, ability); });
    ['defenderSlowStart','defenderUnburden','defenderParadoxBoostStat','defenderFlowerGiftSupport'].forEach(function(id){ moveLabel(id, defAbility); });
    ['metronomeUseCount'].forEach(function(id){ moveLabel(id, item); });
